window.ScripturaLexicons.BDAG_PART_0382 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-01\" data-source=\"BDAG\" data-search=\"Φρόντων, ωνος, ὁ nome próprio masculino Frontão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φρόντων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Frontão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-02\" data-source=\"BDAG\" data-search=\"φρουρά, ᾶς, ἡ substantivo feminino guarda; prisão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρουρά, ᾶς, ἡ</td><td>substantivo feminino</td><td>guarda; prisão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-03\" data-source=\"BDAG\" data-search=\"φρουρέω verbo guardar; deter; proteger BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρουρέω</td><td>verbo</td><td>guardar; deter; proteger</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-04\" data-source=\"BDAG\" data-search=\"φρυάσσω verbo ser arrogante; insolente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρυάσσω</td><td>verbo</td><td>ser arrogante; insolente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-05\" data-source=\"BDAG\" data-search=\"φρύγανον, ου, τό substantivo neutro arbusto; gravetos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρύγανον, ου, τό</td><td>substantivo neutro</td><td>arbusto; gravetos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-06\" data-source=\"BDAG\" data-search=\"Φρυγία, ας, ἡ topônimo feminino Frígia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φρυγία, ας, ἡ</td><td>topônimo feminino</td><td>Frígia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-07\" data-source=\"BDAG\" data-search=\"Φρύξ, γός, ὁ substantivo masculino frígio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φρύξ, γός, ὁ</td><td>substantivo masculino</td><td>frígio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-08\" data-source=\"BDAG\" data-search=\"φυγαδεύω verbo banir; viver no exílio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυγαδεύω</td><td>verbo</td><td>banir; viver no exílio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-09\" data-source=\"BDAG\" data-search=\"Φύγελος (também Φύγελλος), ου, ὁ nome próprio masculino Fígelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φύγελος (também Φύγελλος), ου, ὁ</td><td>nome próprio masculino</td><td>Fígelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-10\" data-source=\"BDAG\" data-search=\"φυγή, ῆς, ἡ substantivo feminino fuga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυγή, ῆς, ἡ</td><td>substantivo feminino</td><td>fuga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-11\" data-source=\"BDAG\" data-search=\"φυλακή, ῆς, ἡ substantivo feminino guarda; sentinela; prisão; vigília BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυλακή, ῆς, ἡ</td><td>substantivo feminino</td><td>guarda; sentinela; prisão; vigília</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-12\" data-source=\"BDAG\" data-search=\"φυλακίζω verbo aprisionar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυλακίζω</td><td>verbo</td><td>aprisionar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-13\" data-source=\"BDAG\" data-search=\"φυλακτήριον, ου, τό substantivo neutro filactério; tira e estojo de oração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυλακτήριον, ου, τό</td><td>substantivo neutro</td><td>filactério; tira e estojo de oração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-14\" data-source=\"BDAG\" data-search=\"φύλαξ, ακος, ὁ substantivo masculino guarda; sentinela BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φύλαξ, ακος, ὁ</td><td>substantivo masculino</td><td>guarda; sentinela</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-15\" data-source=\"BDAG\" data-search=\"φύλαρχος, ου, ὁ substantivo masculino chefe de tribo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φύλαρχος, ου, ὁ</td><td>substantivo masculino</td><td>chefe de tribo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-16\" data-source=\"BDAG\" data-search=\"φυλάσσω verbo vigiar; proteger; evitar; reservar; observar; armazenar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυλάσσω</td><td>verbo</td><td>vigiar; proteger; evitar; reservar; observar; armazenar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-17\" data-source=\"BDAG\" data-search=\"φυλή, ῆς, ἡ substantivo feminino tribo; nação; povo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυλή, ῆς, ἡ</td><td>substantivo feminino</td><td>tribo; nação; povo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-18\" data-source=\"BDAG\" data-search=\"φύλλον, ου, τό substantivo neutro folha; folhagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φύλλον, ου, τό</td><td>substantivo neutro</td><td>folha; folhagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-19\" data-source=\"BDAG\" data-search=\"φυλλοροέω verbo perder as folhas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φυλλοροέω</td><td>verbo</td><td>perder as folhas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0382-20\" data-source=\"BDAG\" data-search=\"φύραμα, ατος, τό substantivo neutro massa; mistura; porção de massa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φύραμα, ατος, τό</td><td>substantivo neutro</td><td>massa; mistura; porção de massa</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0382-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φρόντων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φρόντων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span> (lat. Fronto. A forma grega do nome em Jos., Bell. 6, 238; 242; OGI 533, 34; CIG II add. 2349k; III 5120; IV 9919; IPergamon 511; PGiss 59 II; POxy 1188) Frontão, membro da congregação efésia IEph 2:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρουρά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρουρά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Aeschyl., Hdt. e outros; ins, pap, LXX; TestSol 18:43 P; Philo, Agr. 86 [=guarda pessoal]; Manetho 609 Fgm. 8, 77 p. 85, 12 Jac. [Jos., C. Ap. 1, 77]; Jos., Ant. 7, 104; Mel., P. 15, 98; Ath. 6, 1)</p><p class=\"entry-text\">① o ato ou dever de vigiar, serviço de guarda, serviço como sentinela (Lucian, Ver. Hist. 2, 23) <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">φρουράν</span> montar guarda como sentinela GPt 9:35 (<span class=\"greek\">κατά</span> B 5b<span class=\"greek\">β</span>).</p><p class=\"entry-text\">② lugar para deter uma pessoa sob guarda, prisão (Aeschyl., Prom. 143; BGU 1074, 4 [II d.C.]) em linguagem figurada (Pla., Phdr. 62b; Aelian, HA 4, 41) <span class=\"greek\">Χριστιανοὶ</span> <span class=\"greek\">κατέχονται</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φρουρᾷ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> Dg 6:7 (aparentemente em alusão a Pla., acima).—Frisk. DELG s.v. <span class=\"greek\">φρουρός</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρουρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρουρέω</span> (<span class=\"greek\">φρουρός</span> ‘um guarda’) imperf. <span class=\"greek\">ἐφρούρουν</span>; fut. <span class=\"greek\">φρουρήσω</span>; aor. 3.ª sg. <span class=\"greek\">ἐφρούρησε</span> Jdth 3:6. Pass.: imperf. <span class=\"greek\">ἐφρουρούμην</span> (Aeschyl., Hdt.+) em nossa literatura somente trans.</p><p class=\"entry-text\">① manter vigilância, guardar, lit. <span class=\"greek\">τὶ</span> algo (cf. Jdth 3: 6 <span class=\"greek\">φρ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεις</span>=colocar guarnições nas cidades; Jos., Bell. 3, 12) <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">Δαμασκηνῶν</span> 2 Cor 11:32. Neste caso, a referência é certamente à guarda das portas da cidade pelo lado de dentro, como controle de todos os que saíam (Jos., Vi. 53 <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐξόδους</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πάσας</span> <span class=\"greek\">ἐφρούρει</span>; cf. Nicol. Dam.: 90 Fgm. 130, 51 p. 400, 22 Jac.), e não pelo lado de fora, como por vezes se fazia, p. ex. em cercos (Plut., Crassus 548 [9, 2]; Jos., Vi. 240); Zahn, NKZ 15, 1904, 34ff.</p><p class=\"entry-text\">② manter sob custódia, deter, confinar (Plut., Ant. 954 [84, 4], Mor. 205f; Wsd 17:15; PGM 4, 2905; 3093) fig., pass.: da humanidade antes da vinda de Jesus <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">ἐφρουρούμεθα</span> éramos mantidos sob custódia pela lei Gal 3:23. A terminologia é compatível com o uso romano das prisões principalmente para a detenção de presos até a resolução de seus casos.—Em sentido transferido <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">φρουρεῖται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> Dg 6:4.</p><p class=\"entry-text\">③ geralmente, proporcionar segurança, guardar, proteger, conservar (Soph., Oed. R. 1479 <span class=\"greek\">δαίμων</span> <span class=\"greek\">σε</span> <span class=\"greek\">φρουρήσας</span> <span class=\"greek\">τύχοι</span>; Tat. 15, 3 <span class=\"greek\">τοῖς</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φρουρουμένοις</span> Mel., P. 30, 205) a paz de Deus <span class=\"greek\">φρουρήσει</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ὑμῶν</span> Phil 4:7 (com imagem atenuada da guarda, Straub 30). Pass. 1 Pt 1:5.—DELG s.v. <span class=\"greek\">φρουρός</span>. Frisk s.v. <span class=\"greek\">φρουρά</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρυάσσω</span> 1.º aor. <span class=\"greek\">ἐφρύαξα</span>; perf. médio, partic. gen. <span class=\"greek\">πεφρυαγμένου</span> 3 Macc 2:2 (a ativa somente em Ps 2:1 e no uso neotestamentário dessa passagem. Alhures sempre <span class=\"greek\">φρυάσσομαι</span> [desde Callim., Hymn. 5, 2]; primordialmente em referência aos sons emitidos por animais fogosos, como o ‘resfolegar’ de um cavalo ansioso pela corrida Plut., Lyc. 53 [22, 1] ou o ‘cantar’ de um galo Aelian, NA 7, 7) fig., de pessoas, ser arrogante, altivo, insolente (Diod S 4, 74, 3; Anth. Pal. 4, 3, 27; 2 Macc 7:34 v.l.; 3 Macc 2:2; Philo, Cher. 66) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:25</a> (Ps 2:1).—DELG s.v. <span class=\"greek\">φρυάσσομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρύγανον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρύγανον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">φρύγω</span> ‘assar ou tostar’; Hdt., Aristoph. e outros; ins, pap, LXX)</p><p class=\"entry-text\">① arbusto, moita (Theophr., HP 1, 3, 1 define-o como <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ῥίζης</span> <span class=\"greek\">πολυστέλεχες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πολύκλαδον</span>=cheio de caules e ramos desde a raiz) B 7:8.</p><p class=\"entry-text\">② no pl., pedaços de madeira seca/gravetos, especialmente para acender fogo (cf. o uso do verbo <span class=\"greek\">φρύγω</span> para assar ou cozinhar.—X., An. 4, 3, 11 e outros. Cf. Is 47:14; Philo, In Flacc. 68) Ac 28:3. Com <span class=\"greek\">ξύλα</span> (Diod S 14, 90, 6; Plut., Mor. 525e) lenha miúda para acender fogo MPol 13:1.—DELG s.v. <span class=\"greek\">φρύγω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φρυγία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φρυγία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> Frígia (Hom. e outros; ins, Joseph., SibOr; Tat. 39, 3.—Sobre o uso do artigo, v. B-D-F §261, 6; como adj., v. Hemer, Acts 112 e 283, JTS n.s. 27, ’76, 122–26; também n.s. 28, ’77, 99–101) uma grande região na Ásia Menor central, cujos limites variaram consideravelmente de tempos em tempos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:10</a>; 16:6; 18:23 (nos dois últimos lugares com <span class=\"greek\">ἡ</span> <span class=\"greek\">Γαλατικὴ</span> <span class=\"greek\">χώρα</span>); 1 Ti subscr. (v. <span class=\"greek\">Πακατιανός</span>); MPol 4.—CB (outras publicações de Ramsay em Harnack, Mission4 II 1924 p. 677, 3; WGasque, Sir William M. Ramsay ’66, 86–91); JWeiss, RE X 557ff; VSchultze, Altchristl. Städte u. Landschaften II 1, 1922; AGoltze, Kleinasien2 ’57; Pauly-W. XX 781–891; Kl. Pauly IV 822–26; BHHW III 1468f; WSchepelern, D. Montanismus u. d. phrygischen Kulte 1929.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φρύξ, γός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φρύξ</span>, <span class=\"greek\">γός</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; ins; Just., D. 119, 4; Tat. 1, 1) um frígio (v. <span class=\"greek\">Φρυγία</span>) MPol 4.—DELG s.v. <span class=\"greek\">Φρυγία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυγαδεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυγαδεύω</span> (de <span class=\"greek\">φεύγω</span> por intermédio de <span class=\"greek\">φυγάς</span>, cf. <span class=\"greek\">φυγή</span>) 1.º aor. <span class=\"greek\">ἐφυγάδευσα</span>; pass. <span class=\"greek\">ἐφυγαδεύθην</span></p><p class=\"entry-text\">① fazer tornar-se fugitivo, banir do país, trans. (X. e outros; Diod S 5, 44, 7; ins, pap; TestGad 5:7; Philo, Congr. Erud. Gr. 171) <span class=\"greek\">ἐφυγάδευσεν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">Μωϋσῆν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τούτῳ</span> e com esta palavra expulsou Moisés do país Ac 7:29 v.l. Pass. (Jos., Bell. 1, 661; 4, 504 <span class=\"greek\">φυγαδευθείς</span>, Ant. 12, 399) de Paulo <span class=\"greek\">φυγαδευθείς</span> banido do país ou exilado 1 Cl 5:6.</p><p class=\"entry-text\">② ser fugitivo, viver no exílio, intr. (Polyb. 10, 25, 1; SIG 175, 20 [IV a.C.]; 679, 84 [143 a.C.]; LXX) <span class=\"greek\">οὕτως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐφυγάδευσεν</span> <span class=\"greek\">Μωϋσῆς</span> Ac 7:29 D.—DELG s.v. <span class=\"greek\">φεύγω</span> II B.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φύγελος (também Φύγελλος), ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φύγελος</span> (também <span class=\"greek\">Φύγελλος</span>), <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (sobre o nome e sua grafia, v. B-D-F §42, 3; W-S.§5, 26d; Mlt-H. 101; OBenndorf, Z. Ortskunde u. Stadtgeschichte v. Ephesus 1905, 74) Fígelo, cristão da Ásia, de outro modo desconhecido, que, segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:15,</a> juntamente com Hermógenes, voltou as costas a Paulo.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hom.+; ins, pap, LXX, SibOr, Philo; Jos., Ant 18, 324; 20, 4; Just., A I, 21, 2 <span class=\"greek\">φυγὴ</span> <span class=\"greek\">πόνων</span> evitar a dor) fuga <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:18</a> v.l.—DELG s.v. <span class=\"greek\">φεύγω</span> II A. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυλακή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυλακή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">φύλαξ</span>, cf. <span class=\"greek\">φυλάσσω</span>; Hom.+; ins, pap, LXX, En, TestSol, TestJos; JosAs 4:14; AscIs 2:13; EpArist, Philo, Joseph., Just., D. 131, 6 <span class=\"greek\">φ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κρούους</span>; Ath., R. 18 p. 70, 9 <span class=\"greek\">ἁπάντων</span> <span class=\"greek\">φυλακήν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρόνοιαν</span>; empréstimo na literatura rabínica) ‘vigília, guarda’.</p><p class=\"entry-text\">① o ato de vigiar, guarda, na expressão <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">φυλακάς</span> manter vigilância, fazer serviço de guarda (X., An. 2, 6, 10; Pla., Leg. 6, 758d; Demosth. 7, 14; Plut., Mor. 198a; LXX.—B-D-F §153, 3) <span class=\"greek\">φυλ</span>. <span class=\"greek\">φυλακὰς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ποίμνην</span> vigiar o rebanho à noite (v. <span class=\"greek\">φυλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτός</span> 4 abaixo) Lk 2:8.</p><p class=\"entry-text\">② o ato de guardar personificado, guarda, sentinela (Hom. e outros; OGI 229, 96; 99; PGiss 19, 16; Jos., Bell. 6, 131) Ac 12:10 (a <span class=\"greek\">πρώτη</span> e <span class=\"greek\">δευτέρα</span> <span class=\"greek\">φ</span>. como primeira e segunda sentinelas, como Arrian, Anab. 3, 18, 6).</p><p class=\"entry-text\">③ o lugar em que se exerce a guarda, prisão (no sg. e pl. Hdt., Thu. e outros; OGI 90, 13; 669, 17; pap, LXX; Jos., Vi. 178) <span class=\"greek\">οἶκος</span> <span class=\"greek\">φυλακῆς</span> B 14:7 (Is 42:7). Também simplesmente <span class=\"greek\">φυλακή</span> (TestJos 1:6) Mt 14:10; 25:36, 39, 43f; Mk 6:27; Lk 22:33; Ac 5:19, 22 (sobre fugas de prisões, v. a literatura citada em RPervo, Profit w. Delight ’87, 147 n. 15; v. também <span class=\"greek\">ἀνοίγω</span> 1); 12:6, 17; 16:27, 39 D, 40; Hb 11:36. O pl. de várias prisões (Appian, Bell. Civ. 4, 17 §65) Lk 21:12; Ac 22:4; 26:10; 2 Cor 6:5; 11:23; Hv 3, 2, 1. <span class=\"greek\">βάλλειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φυλακήν</span> (<span class=\"greek\">βάλλω</span> 2; cf. JosAs 4:14 <span class=\"greek\">ἐνέβαλεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φ</span>.) lançar alguém na prisão Mt 18:30 (v. PSchmidt, Die Gesch. Jesu II 1904, 326f); Lk 12:58; Ac 16:23f, 37; Rv 2:10. Pass. Mt 5:25; Lk 23:25; J 3:24; cf. Lk 23:19. <span class=\"greek\">παραδιδόναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φ</span>. (Diod S 11, 40, 3 <span class=\"greek\">παρέδωκαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φ</span>.; 12, 31, 2; 17, 32, 2; OGI 669, 15) Ac 8:3; cf. Lk 21:12. <span class=\"greek\">τίθεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φ</span>. (cf. PEleph 12, 2 [III a.C.]) Ac 12:4. <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῇ</span>) <span class=\"greek\">φυλακῇ</span> <span class=\"greek\">τίθεσθαι</span> Mt 14:3 v.l.; Ac 5:25; <span class=\"greek\">ἀποτίθεσθαι</span> Mt 14:3; <span class=\"greek\">δῆσαι</span> Mk 6:17; <span class=\"greek\">κατακλείειν</span> Lk 3:20; Ac 26:10. <span class=\"greek\">τηρεῖν</span> pass. 12:5. Do mundo inferior ou de seu lugar de punição (<span class=\"greek\">πνεῦμα</span> 2 e 4c) 1 Pt 3:19 (BReicke, The Disobedient Spirits and Christian Baptism ’46, 116f). É numa <span class=\"greek\">φ</span>. neste último sentido que Satanás será tornado inofensivo durante o milênio Rv 20:7. A cidade caída de Babilônia torna-se uma <span class=\"greek\">φυλακή</span> morada de toda espécie de espíritos e aves impuros 18:2ab.</p><p class=\"entry-text\">④ um dos períodos de tempo em que a noite era dividida, uma vigília da noite (Hdt. 9, 51 e outros lugares; Diod S 14, 24, 4 <span class=\"greek\">δευτέρα</span> <span class=\"greek\">φ</span>.; Arrian, Anab. 6, 25, 5 <span class=\"greek\">φυλακὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτός</span>; PPetr II, 45 II, 18 [246 a.C.] <span class=\"greek\">πρώτης</span> <span class=\"greek\">φυλακῆς</span> <span class=\"greek\">ἀρχομένης</span>; LXX; Joseph.). Nossa literatura reflete o costume romano de dividir o tempo entre 6 da tarde e 6 da manhã em quatro períodos iguais ou vigílias (as pessoas designadas eram responsáveis pela segurança durante cada período) Mt 14:25; Mk 6:48 (Diod S 19, 26, 1 <span class=\"greek\">περὶ</span> <span class=\"greek\">δευτέραν</span> <span class=\"greek\">φυλακήν</span>; Jos., Ant. 18, 356 <span class=\"greek\">περὶ</span> <span class=\"greek\">τετάρτην</span> <span class=\"greek\">φυλακήν</span>; para <span class=\"greek\">περί</span> v. também o papiro de Freiburg 76, 7 [II a.C.]: UWilcken, Deissmann Festschr. 1927, 10ff ln. 9f <span class=\"greek\">περὶ</span> <span class=\"greek\">πρώτην</span> <span class=\"greek\">φυλακὴν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νυκτός</span>). Cf. Mt 24:43; Lk 12:38 (aqui talvez devamos pensar em apenas três vigílias noturnas, como entre os hebreus e os gregos [v. Jülicher, Gleichn. 168]: assim Diod, S. 19, 38, 3; Polyaenus 4, 8, 4; Jos., Bell. 5, 510). (Mk 13:35 emprega as designações populares <span class=\"greek\">ὀψέ</span> 2, <span class=\"greek\">μεσονύκτιον</span>, <span class=\"greek\">ἀλεκτοροφωνία</span>, <span class=\"greek\">πρωί̈</span>; v. esses verbetes.)—B. 1451. DELG s.v. <span class=\"greek\">φύλαξ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυλακίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυλακίζω</span> (cf. <span class=\"greek\">φυλακή</span>; Wsd 18:4; TestJos 2:3; Ar. [JTS 25, 1924, p. 74 ln. 23]; Achmes 84, 3; 87, 12) inf. aor. pass. <span class=\"greek\">φυλακισθῆναι</span> Wsd 18:4, partic. pl. <span class=\"greek\">φυλακισθέντας</span> (Ar.) pôr sob custódia, aprisionar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:19</a>; 1 Cl 45:4. V. <span class=\"greek\">φυλακή</span> 3.—DELG s.v. <span class=\"greek\">φύλαξ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυλακτήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυλακτήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">φύλαξ</span>, cf. <span class=\"greek\">φυλάσσω</span>; Hdt.+; TestJob 47:11; Jos., Ant. 15, 249; Just., D. 46, 5; em vários sentidos) tira de couro para oração e estojo que contém passagens das Escrituras, às vezes usado como amuleto, tira de oração, estojo de oração. Um dos sentidos literais de <span class=\"greek\">φ</span>., que ocorre apenas uma vez em nossa literatura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:5,</a> é ‘salvaguarda, meio de proteção’ (Demosth. 6, 24; Philo), especialmente ‘amuleto’ (Dioscor., Mat. Med. 5, 154; Plut., Mor. 377b e outros lugares; OGI 90, 45; PGM 1, 275; 3, 97; 127; 4, 86; 660; 708; 1071; 2506; 2510; 2694; 2705; 13, 796), mas esse sentido é apenas um componente de um fenômeno semântico mais complexo, em que o referente reflete o aramaico <span class=\"hebrew\" dir=\"rtl\">תְפִלִּין</span>, isto é, duas caixas de couro negro contendo passagens das Escrituras, usadas na testa e no braço esquerdo, de acordo com a instrução mosaica Ex 13:9, 16; Dt 6:8; 11:18, onde as diretrizes parecem ser figuradas. A descoberta de tais pequenas caixas, algumas com compartimentos, nas cavernas de Murabbaat confirma ainda mais o testemunho literário da prática. Em alguns círculos os objetos eram considerados amuletos protetores contra influências demoníacas, e essa compreensão se reflete na tradução de Goodspeed (‘usam largos textos das Escrituras como amuletos’), que evita o ambíguo empréstimo inglês ‘phylacteries’.—Schürer II 479–81 (nota 86, literatura; acrescente-se YYadin, Tefillin fr. Qumran ’69); MFriedländer, Der Antichrist 1901, 155ff; GKropatscheck, De Amuletorum apud Antiquos Usu, diss. Greifswald 1907; Billerb. IV 1928, 250–76; GLanger, Die jüd. Gebetsriemen ’31; WKnox, St. Paul and the Church of the Gentiles ’39, 209; GFox, JNES 1, ’42, 373–77; Goodsp., Probs. 35f; CBonner, HTR 39, ’46, 25–53 (esp. 35), Studies in Magical Amulets ’50; JBowman, TU 73, ’59, 523–38; JTigay, HTR 72, ’79, 45–53; Pauly-W. I 467–76; Kl. Pauly IV 834; BHHW I 90f; RAC I 397–411 (literatura).—DELG s.v. <span class=\"greek\">φυλαξ</span> 9. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φύλαξ, ακος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φύλαξ</span>, <span class=\"greek\">ακος</span>, <span class=\"greek\">ὁ</span> (v. os três verbetes anteriores e <span class=\"greek\">φυλάσσω</span>; Hom.+; ins, pap, LXX, JosAs, GrBar, Philo; Jos., Ant. 7, 287 e outros lugares; Just.) guarda, sentinela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:65</a> D, 66 D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:23</a>; 12:6, 19; Dg 2:7; AcPl Ha 3, 25; 4, 4.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φύλαρχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φύλαρχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (X., Pla. e outros; ins, pap, LXX) ‘governante de uma <span class=\"greek\">φυλή</span>’, chefe de uma tribo (X., Cyr. 1, 2, 14; Plut., Crass. 555 [21, 1]; Jos., Ant. 17, 56) dos governantes das 12 tribos hebraicas (Dt 31:28; 1 Esdr 7:8; EpArist 97; Jos., Ant. 3, 169) 1 Cl 43:2ab, 5.—Renehan ’75, 201 (ins). DELG s.v. <span class=\"greek\">φῦλον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυλάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυλάσσω</span> (-<span class=\"greek\">ττ</span>-Ar. [Milne 76, 32]; v. Gignac I 152f) fut. <span class=\"greek\">φυλάξω</span>; 1.º aor. <span class=\"greek\">ἐφύλαξα</span>; perf. <span class=\"greek\">πεφύλαχα</span>. Pass.: 1.º fut. 3.ª pl. <span class=\"greek\">φυλαχθήσονται</span> (TestSol 13:8 C; JosAs 15:6); 1.º aor. <span class=\"greek\">ἐφυλάχθην</span>; perf. 3.ª sg. <span class=\"greek\">πεφύλακται</span> Ezk 18:9, partic. <span class=\"greek\">πεφύλαγμένος</span> LXX (também PsSol 6:2; Just., D. 102, 4) (Hom.+).</p><p class=\"entry-text\">① exercer funções de sentinela, vigiar, guardar, ativa.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">φυλακάς</span> Lk 2:8 (v. também 2 abaixo; <span class=\"greek\">φυλακή</span> 1). <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">φρουράν</span> GPt 9:35 (<span class=\"greek\">φρουρά</span> 1).</p><p class=\"entry-text\">ⓑ <span class=\"greek\">τινά</span> guardar alguém para impedir que a pessoa escape (Plut., Mor. 181a) Mk 15:25 D; Ac 12:4; 28:16. Pass. Lk 8:29; Ac 23:35.</p><p class=\"entry-text\">ⓒ abs. montar guarda (Hom. e outros) GPt 8:33.</p><p class=\"entry-text\">② proteger tomando medidas cuidadosas, guardar, proteger, ativa.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">φυλακάς</span> Lk 2:8 (v. também 1a acima).</p><p class=\"entry-text\">ⓑ com acus. de alguém ou algo. <span class=\"greek\">τινά</span> alguém (ChronLind D, 47 <span class=\"greek\">τούς</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">τούτους</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">φυλάσσουσι</span>; Ex 23:20; Pr 13:6; ParJer 6:10; ApcSed 7:11; ApcMos 7) J 17:12 (com <span class=\"greek\">τηρέω</span> como Dio Chrys. 14 [31], 150); 2 Pt 2:5. De José (no sentido de Mt 1:25) GJs 13:1; 14:2. <span class=\"greek\">τὶ</span> algo (Gen 3:24; TestJob 9:3 <span class=\"greek\">οἶκον</span>; ParJer 3:11 <span class=\"greek\">τὰ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λειτουργίας</span> ApcMos 28) <span class=\"greek\">αὐλήν</span> Lk 11:21. <span class=\"greek\">τὸν</span> <span class=\"greek\">πύργον</span> (EpArist 102) Hs 9, 5, 1. <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">στοιχεῖα</span> Dg 7:2a. Roupas, para impedir que sejam furtadas Ac 22:20. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">αὐτοῦ</span> (<span class=\"greek\">εἰς</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span>) <span class=\"greek\">φυλάσσειν</span> preservar sua vida (para a vida eterna; cf. Jos., Ant. 3, 199 <span class=\"greek\">ἔλαιον</span> <span class=\"greek\">φ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λύχνους</span>) J 12:25. <span class=\"greek\">τὴν</span> <span class=\"greek\">παραθήκην</span> aquilo que foi confiado, para que não se perca nem se danifique 1 Ti 6:20; 2 Ti 1:14; seguido de indicação de tempo (Aelian, VH 9, 21 <span class=\"greek\">ὦ</span> <span class=\"greek\">Ζεῦ</span>, <span class=\"greek\">ἐς</span> <span class=\"greek\">τίνα</span> <span class=\"greek\">με</span> <span class=\"greek\">καιρὸν</span> <span class=\"greek\">φυλάττεις</span>;) <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐκείνην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> v. 12. Cf. B 19:11; D 4:13. <span class=\"greek\">ἀκακίαν</span> 1 Cl 14:5 (Ps 36:37). <span class=\"greek\">θνητὴν</span> <span class=\"greek\">ἐπίνοιαν</span> Dg 7:1. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁγνείαν</span> Hm 4, 1, 1. <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">κτλ</span>. 6, 1, 1. <span class=\"greek\">ὡς</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> 2 Cl 9:3. <span class=\"greek\">τινά</span> com acus. predicativo (Wsd 14:24) <span class=\"greek\">φυλάξαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀπταίστους</span> Jd 24. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (X., Cyr. 1, 4, 7; Menand., Sam. 302f S. [87f Kö.]) 2 Th 3:3 (PGM 4, 2699 <span class=\"greek\">φύλαξόν</span> <span class=\"greek\">με</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">δαίμονος</span>; 36, 177 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">πράγματος</span>; Sir 22:26; Ps 140:9). <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Horapollo 2, 94; Herm. Wr. p. 434, 13 Sc.; TestReub 4:8; JosAs 7:6) 1J 5:21. De uma imagem de culto <span class=\"greek\">χρῄζων</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φυλάξαντος</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κλαπῇ</span> necessitando de uma pessoa para guardá-la, a fim de que não seja furtada Dg 2:2.</p><p class=\"entry-text\">③ estar de guarda contra, acautelar-se de, evitar, média (Hom. e outros; LXX. Test12Patr; ParJer 2:5; Just.) com acus. de pessoa ou coisa evitada <span class=\"greek\">τινά</span> (Aeschyl., Prom. 717; Appian, Bell. Civ. 2, 25 §96 <span class=\"greek\">τὸν</span> <span class=\"greek\">Πομπήιον</span>; 5, 8 §32: Ps.-Liban., Charact. Ep. p. 30, 12; Just., D. 82, 1) 2 Ti 4:15; IEph 7:1; ITr 7:1. <span class=\"greek\">τὶ</span> (Hdt., Aristot. e outros; Jos., Bell. 4, 572) Ac 21:25; ITr 2:3. Também <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (PLond IV, 1349, 35; Dt 23:10; TestSim 4:5; 5:3) Lk 12:15; Hm 5, 1, 7; Hs 5, 3, 6. Seguido de <span class=\"greek\">ἵνα</span> <span class=\"greek\">μή</span> (B-D-F §392, 1b; cf. Gen 31:29; Just., A I, 14, 1 <span class=\"greek\">μή</span>) 2 Pt 3:17.</p><p class=\"entry-text\">④ manter em reserva, guardar, reservar, pass. (Diod S 1, 8, 7) <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> algo para alguém Dg 10:7.</p><p class=\"entry-text\">⑤ continuar a guardar uma lei ou mandamento para que não seja transgredido</p><p class=\"entry-text\">ⓐ ativa, observar, seguir (<span class=\"greek\">νόμον</span> Soph., Trach. 616; Dio Chrys. 58 [75], 1; <span class=\"greek\">νόμους</span> X., Hell. 1, 7, 29; Pla., Rep. 6, 484b, Pol. 292a. Cf. Aristoxenus, Fgm. 18 p. 13, 31 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἤθη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μαθήματα</span>; OGI 669, 28; PTebt 407, 9; POxy 905, 9; PFay 124, 13; Wsd 6:4; Sir 21:11; 4 Macc 5:29; 15:10; Jos., C. Ap. 1, 60; TestJud 26:1; TestIss 5:1; Just., D. 11, 2 e outros lugares; Ath., R. 20 p. 73, 25) <span class=\"greek\">τὶ</span> algo Mt 19:20; Lk 18:21; 1 Ti 5:21; Hm 1:2a; 3:5ab; 4, 4, 3; 8:9; Hs 5, 3, 4. <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> (ViEzk 17 [p. 76, 5 Sch.]; Just., D. 10, 4; Lucian, Jud. 5) Ac 7:53; 21:24; Gal 6:13. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐντολήν</span> Hm 1:2b; 2:7; 8:12a. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span> (Jos., Ant. 6, 336; TestZeb 5:1; TestBenj 10:3, 5; ApcEsdr 5:19; ApcMos 10; Ar. 15:3; Just., D. 46, 4) 2 Cl 8:4; B 4:11; Hv 5, 5, 7; m 2:7; 4, 2, 4ab; 4, 4, 4ab; 5, 2, 8; 12, 5, 1; Hs 5, 3, 2f e outros lugares. Pass. Hm 12, 3, 4f; Hs 1:7. <span class=\"greek\">τὰ</span> <span class=\"greek\">δικαιώματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> as exigências da lei Ro 2:26 (ParJer 6:23 <span class=\"greek\">τὰ</span> <span class=\"greek\">δικαιώματά</span> <span class=\"greek\">μου</span>). <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Lk 11:28. <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> (isto é, de Cristo) J 12:47 (cf. ApcMos 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμα</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">δόγματα</span> Ac 16:4. <span class=\"greek\">φυλ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σάββατον</span> guardar o sábado B 15:2 (cf. Ex 31:16). <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἰουδαίων</span> <span class=\"greek\">δεισιδαιμονίαν</span> <span class=\"greek\">φυλ</span>. praticar o fanatismo/a superstição judaica Dg 1. <span class=\"greek\">τά</span> <span class=\"greek\">μέτρα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">δρόμων</span> <span class=\"greek\">φυλ</span>. 7:2b (<span class=\"greek\">μέτρον</span> 2a).</p><p class=\"entry-text\">ⓑ provavelmente se faz sentir a influência do AT no uso da média pela ativa (v. B-D-F §316, 1) no sentido a: guardar, observar, seguir (Lev 20:22; 26:3; Ps 118:5 e outros lugares. Mas já em Hesiod, Op. 263 <span class=\"greek\">ταῦτα</span> <span class=\"greek\">φυλασσόμενοι</span>=se observardes isto; 765; Ocellus [II a.C.] c. 56 Harder <span class=\"greek\">φυλάττεσθαι</span> <span class=\"greek\">τὸ</span> … <span class=\"greek\">γίνεσθαι</span>) <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πάντα</span> Mt 19:20 v.l.; Mk 10:20; Lk 18:21 v.l.</p><p class=\"entry-text\">⑥ armazenar, acumular para si, média (=‘acautelar-se em benefício próprio’) PtK 2 p. 15, 2.—B. 752. DELG s.v. <span class=\"greek\">φύλαξ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυλή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυλή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">φῦλον</span> ‘raça, tribo, classe’; Pind., Hdt.+).</p><p class=\"entry-text\">① subgrupo de uma nação caracterizado por uma linhagem sanguínea distinta, tribo, das 12 tribos de Israel (Diod S 40, 3, 3 <span class=\"greek\">δώδεκα</span> <span class=\"greek\">φυλαί</span> dos ‘judeus’; LXX; TestAbr A; cf. AscIs 3:2 <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐννέα</span> <span class=\"greek\">ἥμισυ</span> <span class=\"greek\">θυλάς</span>; TestBenj 9:2; Demetr.: 722 Fgm. 6 Jac.; Jos., Ant. 11, 133) Hb 7:13; Rv 7:4; 1 Cl 43:2ab, 4; GJs 1:1; 6:3; AcPl Ha 8, 3. Certas tribos são mencionadas nominalmente: <span class=\"greek\">Ἀσήρ</span> Lk 2:36. <span class=\"greek\">Βενιαμίν</span> Ac 13:21; Ro 11:1; Phil 3:5. <span class=\"greek\">Ἰούδα</span> Rv 5:5; cf. Hb 7:14; todas as tribos Rv 7:5–8 (exceto que, segundo a tradição antiga, Manassés toma o lugar de Dã, visto que esta última é a tribo da qual, por causa de Gen 49:17, se alega que procederá o Anticristo [WBousset, D. Antichrist 1895, 112ff; v. Iren. 5, 30, 2; outras referências Charles, ICC Rv I 208f]). De Maria <span class=\"greek\">ἦν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φυλῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Δαυίδ</span> GJs 10:1b; cf. v. 1a. <span class=\"greek\">αἱ</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">φυλαὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span> Mt 19:28; Lk 22:30; cf. Rv 21:12; B 8:3ab; <span class=\"greek\">πᾶσαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">φ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> GJs 24:3; em linguagem figurada Js 1:1; Hs 9, 17, 1f.</p><p class=\"entry-text\">② grupo relativamente numeroso de pessoas que constitui um subgrupo sociopolítico da raça humana, nação, povo (X., Cyr. 1, 2, 5; Dionys. Hal. 2, 7) <span class=\"greek\">πᾶσαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">φυλαὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> (Gen 12:3; 28:14; Ezk 20:32) Mt 24:30; Rv 1:7; 1 Cl 10:3 (Gen 12:3). Com expressões sinônimas (TestAsh 7:6 <span class=\"greek\">χώρα</span>, <span class=\"greek\">φυλή</span>, <span class=\"greek\">γλῶσσα</span>) <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span>, <span class=\"greek\">φυλὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γλώσσας</span> 2 Cl 17:4; cf. Rv 5:9; 7:9; 11:9; 13:7; 14:6.—B. 1317. DELG s.v. <span class=\"greek\">φῦλον</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φύλλον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φύλλον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom. e outros; pap, LXX, En; TestSol [também PVindob 18, 37]; ApcSed 8:8; ApcMos 20) folha 1 Cl 23:4 (citação das Escrituras de origem desconhecida). Coletivamente, folhagem B 11:6 (Ps 1:3). Alhures em nossa literatura (como predominantemente em Lucian) no pl. (En 24:4; EpArist 70; Jos., Ant. 1, 44; 3, 174; TestLevi 9:12; ApcSed, ApcMos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:19</a>; 24:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:13ab</a>; 13:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2</a>; B 11:8; Hs 3:1. <span class=\"greek\">ἀποβάλλειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">φ</span>. 3:3.—B. 525. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυλλοροέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φυλλοροέω</span> (<span class=\"greek\">φύλλον</span>, <span class=\"greek\">ῥέω</span>; Pherecrates Com. [V a.C.], Fgm. 130, 10 Kock [em Athen. p. 269d]; Plut., Mor. 648d; 649cd; 723e; Epict. 1, 14, 3; 3, 24, 91. Predominantemente com <span class=\"greek\">ρ</span> duplo: <span class=\"greek\">φυλλορροέω</span> [X.; Artem. 4, 57; Aristaen., Ep. 1, 10; Philo, Ebr. 9 e outros lugares]) deixar cair as folhas, perder a folhagem 1 Cl 23:4=2 Cl 11:3 (dito profético de origem desconhecida).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0382-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φύραμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φύραμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">φυράω</span> ‘misturar substâncias’)</p><p class=\"entry-text\">① aquilo que é misturado/amassado, mistura/porção de massa (Aristot., Probl. 21, 18, 929a, 25; Plut., Mor. 693e; PTebt 401, 27 [I d.C.]; Num 15:20f) <span class=\"greek\">μικρὰ</span> <span class=\"greek\">ζύμη</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φύραμα</span> <span class=\"greek\">ζυμοῖ</span> 1 Cor 5:6; Gal 5:9 (<span class=\"greek\">ζύμη</span> 1). Sobre Ro 11:16 cf. Num 15:20f. Metaf. (Philo, Sacr. Abel. 108): os cristãos devem ser <span class=\"greek\">νέον</span> <span class=\"greek\">φύραμα</span> massa fresca que não contém fermento 1 Cor 5:7 (cf. Philo, Spec. Leg. 2, 158 <span class=\"greek\">φυράμαπα</span> <span class=\"greek\">ἄζυμα</span>; cf. a advertência contra a tolerância de fornicadores na congregação).</p><p class=\"entry-text\">② a mistura semelhante à massa de que os oleiros fazem seus artefatos, porção de massa (Plut., Mor. 811c) Ro 9:21.—B. 360. DELG s.v. <span class=\"greek\">φύρω</span>. M-M.</p></section></article>"};
